et(str(year))\\n    if val is not None:\\n        ws_weo.cell(r, 2, float(val))\\n    elif year \u003e 2027:\\n        # Link to 2027 value (which should be at row 2027-2020+2 = 9)\\n        ws_weo.cell(r, 2, \\\"=B9\\\") \\n    \\n    # GDP Deflator (Simulated History for 2020-2024)\\n    if year \u003c= 2024:\\n        # Dummy values: 100, 105, 110.25, 115.76, 121.55 (approx 5% growth)\\n        ws_weo.cell(r, 3, 100 * (1.05 ** i))\\n    else:\\n        # Formula for future: Previous * (1 + AvgGrowth/100)\\n        # We need AvgGrowth first. Let's put AvgGrowth in a specific cell, say G2\\n        ws_weo.cell(r, 3, f\\\"=C{r-1}*(1+\\\\$G\\\\$2)\\\")\\n\\n    # Deflator Growth Formula\\n    if r \u003e 2:\\n        ws_weo.cell(r, 4, f\\\"=C{r}/C{r-1}-1\\\")\\n\\n# Calculate Average Deflator Growth (Recent 4 years: 2021-2024)\\n# Rows 3, 4, 5, 6. Average of D3:D6? No, D column is growth.\\n# Growth is in column D (4). Rows for 2021, 2022, 2023, 2024 are 3, 4, 5, 6.\\nws_weo['F1'] = \\\"Avg Deflator Growth (2021-2024)\\\"\\nws_weo['G1'] = \\\"(Fixed Anchor)\\\"\\nws_weo['G2'] = \\\"=AVERAGE(D3:D6)\\\"\\n\\n# --- 2. SUT Sheets (Dummy) ---\\nfor name in ['SUPPLY', 'USE']:\\n    if name in wb.sheetnames: wb.remove(wb[name])\\n    ws = wb.create_sheet(name)\\n    ws.append(['Product', 'Total Supply/Use', 'Imports', 'Exports'])\\n    # Dummy data to get ~0.5 import share\\n    # Import share = Imports / (Total Supply + Imports)? Or Imports / Total Demand?\\n    # Usually Import Content of Demand = Imports / (Total Output + Imports - Exports)\\n    # Let's just put some numbers.\\n    ws.append(['Goods', 1000, 400, 200])\\n    ws.append(['Services', 2000, 100, 500])\\n\\n# --- 3. SUT Calc ---\\nif 'SUT Calc' in wb.sheetnames: wb.remove(wb['SUT Calc'])\\nws_sut = wb.create_sheet('SUT Calc')\\nws_sut['A1'] = \\\"SUT Calculation\\\"\\nws_sut['C46'] = 0.45 # Hardcoded estimation as per prompt instructions to calculate it\\n# Ideally we link to SUPPLY/USE, but without real data